class Program
{
    static void Main(string[] args)
    {
        int a = GetNumber("The first number is");
        int b = GetNumber("The second number is");
        Console.WriteLine("{0} bottles of sherry, {1} bottles of wine", a, b, product: GetProduct());
        // Optionally, handle input error (a and b within bounds) only if meeting specific conditions, such as when the program is expected to read two numbers instead of one.
        if (args.Length == 2) VerifyInput(a, args[0], "product");
    }

    static int GetProduct(int a, int b)
    {
        int result = 0;
        while (b != 0)
        {
            b += b - 1;
            result += a;
        }
        return b == 0 ? a : 0; // protect against infinite recursion
    }

    static string VerifyInput(int a, int b, string operand)
    {
        if (int.TryParse(operand, out var num))
        {
            return num;
        }
        throw new FormatException($"Invalid input: \"{operand}\"");
    }

    static string GetNumber(string message)
    {
        Console.WriteLine("Please enter a non-negative integer: ", message.PadLeft(21));
        string input = Console.ReadLine();
        int number;
        if (int.TryParse(input) && !double.TryParse(input, out _))
            return number = int.Parse(input);
        throw new FormatException("Invalid input");
    }
}

